"""Inbound rate limit for the ``/search`` entrypoint.

This is a plain in-process limiter.  Unlike the IP based bot detection of
:ref:`botdetection` it does not require Valkey: this instance runs as a single
threaded Flask process (``webapp.run`` passes ``threaded=True``), so one shared
counter is authoritative.

Two independent rules, both keyed on the entrypoint rather than on a search
engine, because one request fans out to every enabled engine internally:

- ``rate_limit.per_minute`` -- sliding window of admitted requests.  A request
  beyond the quota is rejected with HTTP 429 and a ``Retry-After`` header.
- ``rate_limit.min_interval`` -- minimum delay between two admitted requests.
  A request arriving too early is *held* until the interval is met instead of
  being rejected, so the client never loses a request.

Only ``/search`` is metered; the homepage, ``/preferences``, ``/healthz``,
static assets and the image proxy are left untouched.
"""

import logging
import time
from collections import deque
import threading

from flask import Response, jsonify, request

import searx

logger = logging.getLogger('searx.rate_limit')

TARGET_PATH = '/search'
WINDOW_SECONDS = 60.0

#: monotonic timestamps of the requests admitted within the current window
_admitted: deque = deque()
#: earliest time at which the next request may be admitted
_next_slot: float = 0.0
_lock = threading.Lock()


def _get_cfg() -> tuple[int, float]:
    """Return ``(per_minute, min_interval)``.

    Read on every call instead of being cached: ``searx.settings`` is only
    populated during ``init()``, so a value captured at import time would be
    empty.  A missing, unparsable or non positive value switches the rule off.
    """
    per_minute = searx.get_setting('rate_limit.per_minute', 10)
    min_interval = searx.get_setting('rate_limit.min_interval', 0.5)
    try:
        per_minute = int(per_minute)
        min_interval = float(min_interval)
    except (TypeError, ValueError):
        per_minute, min_interval = 10, 0.5
    return per_minute, max(min_interval, 0.0)


def _too_many_response(retry_after: int) -> tuple[Response, int, dict]:
    """429 body.  ``before_request`` has no access to the preferences, so
    ``webapp.index_error`` cannot be reused here."""
    if request.args.get('format') == 'json':
        body: Response = jsonify({'error': 'too many requests', 'retry_after': retry_after})
    else:
        body = Response('Too Many Requests', mimetype='text/plain')
    return body, 429, {'Retry-After': str(retry_after)}


def _retry_after() -> int:
    """Seconds until the oldest timestamp of the window leaves it."""
    oldest = _admitted[0]
    return max(1, int(oldest + WINDOW_SECONDS - time.monotonic()) + 1)


def _prune(now: float) -> None:
    while _admitted and _admitted[0] <= now - WINDOW_SECONDS:
        _admitted.popleft()


def _guard():
    """``before_request`` hook.  Returning a Response short-circuits the request."""
    global _next_slot  # pylint: disable=global-statement

    if request.path != TARGET_PATH:
        return None

    per_minute, min_interval = _get_cfg()
    if per_minute <= 0:
        return None

    now = time.monotonic()

    with _lock:
        _prune(now)

        # fast fail: refuse before holding this worker thread in the queue
        if len(_admitted) >= per_minute:
            return _too_many_response(_retry_after())

        if now >= _next_slot:
            wait = 0.0
            _next_slot = now + min_interval
        else:
            # claim the next slot now, before sleeping: two requests that would
            # read the same _next_slot must not wake up at the same moment
            wait = _next_slot - now
            _next_slot = _next_slot + min_interval

    if wait > 0:
        time.sleep(wait)

    # re-check the quota after waiting: earlier requests may have filled the
    # window in the meantime, so the quota is reserved at admission time
    with _lock:
        now = time.monotonic()
        _prune(now)
        if len(_admitted) >= per_minute:
            return _too_many_response(_retry_after())
        _admitted.append(now)

    return None


def install(app) -> None:
    """Register the guard.

    Called from ``limiter.initialize`` before its early return, because with
    ``server.limiter`` disabled that function does not install any hook at
    all.
    """
    app.before_request(_guard)
    per_minute, min_interval = _get_cfg()
    logger.info(
        'rate_limit: %s limited to %d request(s) per %d s, min. interval %.2f s',
        TARGET_PATH, per_minute, int(WINDOW_SECONDS), min_interval,
    )
